// Pesos por defecto: planitud, zancada, despeje y uniformidad de velocidad
const w1 = 3.0, w2 = 1.0, w3 = 1.0, w4 = 1.0;
const { dx, dy, L, r3, p, alpha } = vars;

const N = 60;
if (!globalThis._walkPx) {
  globalThis._walkPx = new Float64Array(60);
  globalThis._walkPy = new Float64Array(60);
  globalThis._walkCos = new Float64Array(60);
  globalThis._walkSin = new Float64Array(60);
  for (let s = 0; s < 60; s++) {
    const th = (2 * Math.PI * s) / 60;
    globalThis._walkCos[s] = Math.cos(th);
    globalThis._walkSin[s] = Math.sin(th);
  }
}
const px = globalThis._walkPx;
const py = globalThis._walkPy;
const cTable = globalThis._walkCos;
const sTable = globalThis._walkSin;

const L2 = L * L, r3_2 = r3 * r3;
const L_plus_r3 = L + r3, L_minus_r3 = Math.abs(L - r3);

let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;

for (let s = 0; s < N; s++) {
  const ax = cTable[s], ay = sTable[s];
  const vx = dx - ax, vy = dy - ay;
  const d2 = vx * vx + vy * vy;
  const d = Math.sqrt(d2);
  if (d <= 1e-9 || d > L_plus_r3 || d < L_minus_r3) return 1000 + (N - s) * 10;
  const a = (L2 - r3_2 + d2) / (2 * d);
  const h2 = L2 - a * a;
  const h = Math.sqrt(h2 > 0 ? h2 : 0);
  const mx = ax + (a * vx) / d, my = ay + (a * vy) / d;
  const bx = mx + (h * vy) / d, by = my - (h * vx) / d;
  const phi = Math.atan2(by - ay, bx - ax) + alpha;
  const curX = ax + p * Math.cos(phi);
  const curY = ay + p * Math.sin(phi);
  px[s] = curX;
  py[s] = curY;
  if (curX < minX) minX = curX;
  if (curX > maxX) maxX = curX;
  if (curY < minY) minY = curY;
  if (curY > maxY) maxY = curY;
}

const alturaTotal = maxY - minY;
if (alturaTotal <= 1e-6) return 800;
const diagCaja = Math.hypot(maxX - minX, alturaTotal);

for (let s = 0; s < N; s++) {
  const sNext = (s + 1) % N;
  if (Math.hypot(px[sNext] - px[s], py[sNext] - py[s]) > 0.25 * diagCaja) return 500;
}

// Fase de apoyo: 35% de pasos inferiores
const umbralY = minY + alturaTotal * 0.35;
let minYApoyo = Infinity, maxYApoyo = -Infinity, minXApoyo = Infinity, maxXApoyo = -Infinity, sumaYApoyo = 0;
let conteoApoyo = 0;

for (let s = 0; s < N; s++) {
  const y = py[s];
  if (y <= umbralY) {
    conteoApoyo++;
    const x = px[s];
    if (y < minYApoyo) minYApoyo = y;
    if (y > maxYApoyo) maxYApoyo = y;
    if (x < minXApoyo) minXApoyo = x;
    if (x > maxXApoyo) maxXApoyo = x;
    sumaYApoyo += y;
  }
}
if (conteoApoyo === 0) return 800;
const anchoApoyo = maxXApoyo - minXApoyo;
if (anchoApoyo <= 1e-6) return 800;
const mediaYApoyo = sumaYApoyo / conteoApoyo;

const f1 = (maxYApoyo - minYApoyo) / alturaTotal;
const f2 = 1 - Math.min(1, anchoApoyo / L_plus_r3);
const f3 = Math.max(0, 0.3 - (maxY - mediaYApoyo) / anchoApoyo) / 0.3;

let sumaDx = 0, sumaAbsDx = 0, nDx = 0;
for (let s = 0; s < N; s++) {
  const sNext = (s + 1) % N;
  if (py[s] <= umbralY && py[sNext] <= umbralY) {
    const dX = px[sNext] - px[s];
    sumaDx += dX;
    sumaAbsDx += Math.abs(dX);
    nDx++;
  }
}
let f4 = 1.0;
if (nDx >= 3 && sumaAbsDx > 1e-6) {
  const promDx = sumaDx / nDx;
  let varDx = 0;
  for (let s = 0; s < N; s++) {
    const sNext = (s + 1) % N;
    if (py[s] <= umbralY && py[sNext] <= umbralY) {
      const diff = (px[sNext] - px[s]) - promDx;
      varDx += diff * diff;
    }
  }
  const desvio = Math.sqrt(varDx / nDx);
  f4 = Math.min(1, desvio / (sumaAbsDx / nDx));
}

return w1 * f1 + w2 * f2 + w3 * f3 + w4 * f4;
